[[noreturn]] void cannotWrite(std::string_view type)
{
    throw NES::FormattingError("MEOS cannot write a value of {}", type);
}

[[noreturn]] void cannotRead(std::string_view type, std::string_view text)
{
    throw NES::CannotFormatSourceData("MEOS reads no value of {} from '{}'", type, text);
}

/// The upper-case hex of the bytes, the text MobilityFlink renders a WKB in.
std::string hex(std::span<const std::byte> bytes)
{
    static constexpr std::string_view digits = "0123456789ABCDEF";
    std::string text;
    text.reserve(2 * bytes.size());
    for (const auto byte : bytes)
    {
        text.push_back(digits[std::to_integer<uint8_t>(byte) >> 4U]);
        text.push_back(digits[std::to_integer<uint8_t>(byte) & 0xFU]);
    }
    return text;
}

/// The bytes the hex states, as the MEOS WKB readers take them.
std::vector<uint8_t> unhex(std::string_view text)
{
    const auto digit = [text](const char c) -> uint8_t
    {
        if (c >= '0' and c <= '9')
        {
            return c - '0';
        }
        if (c >= 'A' and c <= 'F')
        {
            return c - 'A' + 10;
        }
        if (c >= 'a' and c <= 'f')
        {
            return c - 'a' + 10;
        }
        throw NES::CannotFormatSourceData("'{}' is not hexadecimal", text);
    };
    if (text.size() % 2 != 0)
    {
        throw NES::CannotFormatSourceData("'{}' has an odd number of hexadecimal digits", text);
    }
    std::vector<uint8_t> bytes(text.size() / 2);
    for (size_t i = 0; i < bytes.size(); ++i)
    {
        bytes[i] = static_cast<uint8_t>((digit(text[2 * i]) << 4U) | digit(text[2 * i + 1]));
    }
    return bytes;
}

/// A copy of the bytes the span holds.
template <typename T>
std::vector<std::byte> bytesOf(std::span<const T> held)
{
    const auto bytes = std::as_bytes(held);
    return {bytes.begin(), bytes.end()};
}

/// The string the bytes hold.
std::string textOf(std::span<const std::byte> bytes)
{
    std::string text(bytes.size(), '\0');
    std::memcpy(text.data(), bytes.data(), bytes.size());
    return text;
}

/// The value whose memory image the bytes hold, as the catalog's copy function copies it from the image
/// laid in memory malloc allocates, as MEOS allocates, which aligns it for any type.
void* fromImage(std::span<const std::byte> bytes, void* (*copy)(const void*))
{
    void* laid = std::malloc(bytes.size());
    std::memcpy(laid, bytes.data(), bytes.size());
    void* value = copy(laid);
    std::free(laid);
    return value;
}

/// The memory image of the value, the size bytes it is laid in.
std::vector<std::byte> image(const void* value, const size_t size)
{
    std::vector<std::byte> bytes(size);
    std::memcpy(bytes.data(), value, size);
    return bytes;
}

/// The text of the array the bytes carry (its number of elements, then each element after its length) in the form
/// PostgreSQL's array_out writes a one-dimensional array: the texts element writes, in braces, separated by commas,
/// a text quoted where it is empty, is NULL or holds a brace, a comma, a double quote, a backslash or white space,
/// each double quote and backslash in it escaped by a backslash. No bytes are no value, written as the empty text.
std::string arrayToText(std::span<const std::byte> bytes, std::string (*element)(std::span<const std::byte>))
{
    if (bytes.empty())
    {
        return {};
    }
    uint32_t count = 0;
    std::memcpy(&count, bytes.data(), sizeof(count));
    size_t at = sizeof(count);
    std::string text{"{"};
    for (uint32_t i = 0; i < count; ++i)
    {
        uint32_t size = 0;
        std::memcpy(&size, bytes.data() + at, sizeof(size));
        at += sizeof(size);
        const auto written = element(bytes.subspan(at, size));
        at += size;
        if (i > 0)
        {
            text += ',';
        }
        const bool quoted = written.empty() or strcasecmp(written.c_str(), "NULL") == 0
            or written.find_first_of("{},\"\\ \t\n\r\v\f") != std::string::npos;
        if (not quoted)
        {
            text += written;
            continue;
        }
        text += '"';
        for (const char c : written)
        {
            if (c == '"' or c == '\\')
            {
                text += '\\';
            }
            text += c;
        }
        text += '"';
    }
    text += '}';
    return text;
}

/// The bytes of the array of `type` the text states in the form PostgreSQL's array_in reads a one-dimensional
/// array (braces around elements separated by commas, an element quoted in double quotes or not, a backslash
/// escaping the character after it, the white space around an unquoted element dropped), each element read by
/// element; an array of MEOS values holds no NULL.
std::vector<std::byte> arrayFromText(std::string_view text, std::string_view type, std::vector<std::byte> (*element)(std::string_view))
{
    const auto space = [](const char c) { return c == ' ' or c == '\t' or c == '\n' or c == '\r' or c == '\v' or c == '\f'; };
    size_t at = 0;
    const auto skip = [&]
    {
        while (at < text.size() and space(text[at]))
        {
            ++at;
        }
    };
    skip();
    if (at == text.size() or text[at] != '{')
    {
        cannotRead(type, text);
    }
    ++at;
    std::vector<std::byte> carried(sizeof(uint32_t));
    uint32_t count = 0;
    skip();
    bool closed = at < text.size() and text[at] == '}';
    if (closed)
    {
        ++at;
    }
    while (not closed)
    {
        skip();
        std::string value;
        if (at < text.size() and text[at] == '"')
        {
            ++at;
            while (at < text.size() and text[at] != '"')
            {
                if (text[at] == '\\')
                {
                    ++at;
                }
                if (at < text.size())
                {
                    value += text[at++];
                }
            }
            if (at == text.size())
            {
                cannotRead(type, text);
            }
            ++at;
            skip();
        }
        else
        {
            size_t kept = 0;
            while (at < text.size() and text[at] != ',' and text[at] != '}')
            {
                if (text[at] == '{' or text[at] == '"')
                {
                    cannotRead(type, text);
                }
                if (text[at] == '\\' and at + 1 < text.size())
                {
                    ++at;
                    value += text[at++];
                    kept = value.size();
                    continue;
                }
                value += text[at++];
                if (not space(value.back()))
                {
                    kept = value.size();
                }
            }
            value.resize(kept);
            if (value.empty() or strcasecmp(value.c_str(), "NULL") == 0)
            {
                cannotRead(type, text);
            }
        }
        if (at == text.size() or (text[at] != ',' and text[at] != '}'))
        {
            cannotRead(type, text);
        }
        closed = text[at++] == '}';
        const auto bytes = element(value);
        const auto size = static_cast<uint32_t>(bytes.size());
        const auto from = carried.size();
        carried.resize(from + sizeof(size) + size);
        std::memcpy(carried.data() + from, &size, sizeof(size));
        std::memcpy(carried.data() + from + sizeof(size), bytes.data(), size);
        ++count;
    }
    skip();
    if (at != text.size())
    {
        cannotRead(type, text);
    }
    std::memcpy(carried.data(), &count, sizeof(count));
    return carried;
}

/* bigintset: C type Set, carried as its memory image (set_copy / set_mem_size), read and written as the hex of its WKB */
std::string BigintsetToText(std::span<const std::byte> bytes)
{
    if (bytes.empty())
    {
        return {};
    }
    MEOS::Meos::ensureMeosInitialized();
    auto* value = static_cast<Set*>(fromImage(bytes, [](const void* laid) -> void* { return set_copy(static_cast<const Set*>(laid)); }));
    size_t size = 0;
    auto* written = set_as_wkb(value, 4, &size);
    std::free(value);
    if (written == nullptr) { cannotWrite("bigintset"); }
    auto text = hex(std::as_bytes(std::span{written, size}));
    std::free(written);
    return text;
}

std::vector<std::byte> BigintsetFromText(std::string_view text)
{
    MEOS::Meos::ensureMeosInitialized();
    const auto wkb = unhex(text);
    auto value = set_from_wkb(wkb.data(), wkb.size());
    if (value == nullptr) { cannotRead("bigintset", text); }
    auto carried = image(value, static_cast<size_t>(set_mem_size(value)));
    std::free(value);
    return carried;
}

